const crypto = require('node:crypto');
const fs = require('node:fs/promises');
const os = require('node:os');
const path = require('node:path');
const {
    buildAgentCommand, buildAgentExecutionCommand, buildAgentStreamingCommand, CODEX_MAX_THINKING_LEVEL,
    defaultModelForProfile, supportsModelDiscovery, validateAgentProfiles,
} = require('../../../../shared/agent_profiles.mjs');
const { validateAgentModelCatalog, validateCatalogSelection } = require('../../../../shared/agent_model_catalog.mjs');
const { resolveAgentCommand } = require('./agent_profiles.mjs');
const { AgentExecutableResolver } = require('./agent_executable_availability');
const { createAgentEnvironment } = require('./agent_environment');
const { AgentCatalogProcess } = require('./agent_catalog_process');
const { readCodexModelCatalog } = require('./codex_model_catalog');
const { CLAUDE_CATALOG_ARGUMENTS, readClaudeModelCatalog } = require('./claude_model_catalog');

const CATALOG_TTL_MS = 5 * 60 * 1000;
const MAX_CATALOG_CONTEXTS = 32;
const MAX_CONCURRENT_PROBES = 4;
const MAX_CONFIGURATION_ANCESTORS = 32;

async function fileFingerprint(filePath) {
    try {
        const metadata = await fs.stat(filePath);

        return [filePath, metadata.size, metadata.mtimeMs];
    } catch (error) {
        if (error.code === 'ENOENT') return [filePath, null];
        throw error;
    }
}

async function settingsFingerprint(agent, cwd, environment) {
    const userDirectory = agent === 'codex'
        ? environment.CODEX_HOME ?? path.join(os.homedir(), '.codex')
        : environment.CLAUDE_CONFIG_DIR ?? path.join(os.homedir(), '.claude');
    const files = agent === 'codex'
        ? ['config.toml', 'requirements.toml', 'auth.json', 'models_cache.json'].map((name) => path.join(userDirectory, name))
        : [path.join(userDirectory, 'settings.json'), path.join(userDirectory, '.credentials.json'), path.join(os.homedir(), '.claude.json')];
    let directory = cwd;
    for (let depth = 0; depth < MAX_CONFIGURATION_ANCESTORS; depth++) {
        files.push(...(agent === 'codex'
            ? [path.join(directory, '.codex', 'config.toml')]
            : [path.join(directory, '.claude', 'settings.json'), path.join(directory, '.claude', 'settings.local.json')]));
        const parent = path.dirname(directory);
        if (parent === directory) break;
        directory = parent;
    }

    return await Promise.all(files.map(fileFingerprint));
}

/** Own authoritative host catalogs, bounded probe lifecycles, and execution capability checks. */
class AgentModelCatalogService {
    constructor(dependencies = {}) {
        this.executableResolver = dependencies.executableResolver ?? new AgentExecutableResolver();
        this.createProbe = dependencies.createProbe ?? ((agent) => new AgentCatalogProcess(agent));
        this.fingerprint = dependencies.fingerprint ?? fileFingerprint;
        this.settingsFingerprint = dependencies.settingsFingerprint ?? settingsFingerprint;
        this.environment = dependencies.environment ?? process.env;
        this.now = dependencies.now ?? Date.now;
        this.cache = new Map();
        this.pending = new Map();
        this.activeProbes = new Set();
    }

    async load(profileValue, cwd, refresh = false) {
        const [profile] = validateAgentProfiles([profileValue]);
        if (typeof cwd !== 'string' || !path.isAbsolute(cwd)) throw new Error('Model catalog requires an absolute working directory');
        if (!supportsModelDiscovery(profile)) {
            return validateAgentModelCatalog({
                agent: profile.name, provider: profile.name, source: 'configured', fetchedAt: this.now(),
                models: profile.models.map((id) => ({ id, displayName: id, hidden: false, reasoningEfforts: [], serviceTiers: [] })),
            });
        }
        const environment = createAgentEnvironment(this.environment, profile.name);
        const command = buildAgentCommand(profile, defaultModelForProfile(profile));
        const executable = await this.executableResolver.find(command[0], { cwd, env: environment });
        if (!executable) throw new Error(`Executable not found for ${profile.name}: ${command[0]}`);
        const fingerprints = await Promise.all([
            this.fingerprint(executable),
            this.settingsFingerprint(profile.name, cwd, environment),
        ]);
        const key = crypto.createHash('sha256').update(JSON.stringify([profile, executable, cwd, environment, fingerprints])).digest('hex');
        if (refresh) this.cache.delete(key);
        const cached = this.cache.get(key);
        if (cached && this.now() - cached.fetchedAt < CATALOG_TTL_MS) return cached;
        const pending = this.pending.get(key);
        if (pending) return await pending;
        if (this.activeProbes.size >= MAX_CONCURRENT_PROBES) throw new Error('Model discovery is busy; retry shortly');
        const request = this.discover(profile, executable, command.slice(1), cwd, environment, key);
        this.pending.set(key, request);
        try {
            return await request;
        } finally {
            this.pending.delete(key);
        }
    }

    async discover(profile, executable, argumentsList, cwd, environment, key) {
        const probe = this.createProbe(profile.name);
        this.activeProbes.add(probe);
        try {
            const catalogArguments = profile.name === 'codex' ? ['app-server', '--stdio'] : CLAUDE_CATALOG_ARGUMENTS;
            probe.start(executable, [...argumentsList, ...catalogArguments], { cwd, env: environment });
            const result = profile.name === 'codex'
                ? await readCodexModelCatalog(probe, cwd)
                : await readClaudeModelCatalog(probe);
            const catalog = validateAgentModelCatalog({agent: profile.name, provider: result.provider, source: 'runtime', fetchedAt: this.now(), executable, models: result.models});
            if (this.cache.size >= MAX_CATALOG_CONTEXTS) this.cache.delete(this.cache.keys().next().value);
            this.cache.set(key, catalog);

            return catalog;
        } finally {
            try {
                await probe.close();
            } finally {
                this.activeProbes.delete(probe);
            }
        }
    }

    async resolveExecution(config, selection, streaming, cwd) {
        const resolved = resolveAgentCommand(config, selection, streaming);
        const catalog = await this.load(resolved.profile, cwd);
        const { serviceTier } = validateCatalogSelection(catalog, resolved);
        const speedSettings = { speedMode: resolved.speedMode, serviceTier };
        const command = streaming
            ? buildAgentStreamingCommand(
                resolved.profile, resolved.model, resolved.thinkingLevel, resolved.permissionMode, speedSettings,
            )
            : buildAgentExecutionCommand(
                resolved.profile, resolved.model, resolved.thinkingLevel,
                config.codexSearchEnabled ?? true, resolved.permissionMode, speedSettings,
            );
        const reasoningEffort = resolved.agent === 'codex' && resolved.thinkingLevel === 'max'
            ? CODEX_MAX_THINKING_LEVEL : resolved.thinkingLevel;
        const executionSettings = {
            model: resolved.model,
            ...(resolved.thinkingLevel !== 'none' ? { effort: reasoningEffort } : {}),
            ...(serviceTier !== undefined ? { serviceTier } : {}),
        };

        return { ...resolved, command, executionSettings };
    }

    async stop() {
        for (const probe of this.activeProbes) await probe.close();
        this.activeProbes.clear();
        this.cache.clear();
    }
}

module.exports = { AgentModelCatalogService };

const crossSpawn = require('cross-spawn');
const { StringDecoder } = require('node:string_decoder');
const { terminateProcessTree } = require('../process_tree');
const { redactSecrets } = require('./agent_secret_redaction');

const CATALOG_TIMEOUT_MS = 20_000;
const CATALOG_MAX_OUTPUT_BYTES = 2 * 1024 * 1024;
const CATALOG_MAX_REQUESTS = 24;

/** Own one bounded, no-inference JSONL discovery process and its pending protocol requests. */
class AgentCatalogProcess {
    constructor(agent, dependencies = {}) {
        this.agent = agent;
        this.spawn = dependencies.spawn ?? crossSpawn;
        this.terminateProcessTree = dependencies.terminateProcessTree ?? terminateProcessTree;
        this.timeoutMs = dependencies.timeoutMs ?? CATALOG_TIMEOUT_MS;
        this.maximumOutputBytes = dependencies.maximumOutputBytes ?? CATALOG_MAX_OUTPUT_BYTES;
        this.child = null;
        this.closed = false;
        this.failure = null;
        this.buffer = '';
        this.decoder = new StringDecoder('utf8');
        this.secretValues = new Set();
        this.outputBytes = 0;
        this.requestSequence = 0;
        this.pending = new Map();
        this.timer = null;
        this.handleOutput = this.handleOutput.bind(this);
        this.handleStderr = this.handleStderr.bind(this);
        this.handleError = this.handleError.bind(this);
        this.handleExit = this.handleExit.bind(this);
        this.handleTimeout = this.handleTimeout.bind(this);
    }

    start(executable, argumentsList, options) {
        this.secretValues = new Set(Object.entries(options.env)
            .filter(([name, value]) => /token|secret|password|api.?key/iu.test(name) && typeof value === 'string' && value.length > 0)
            .map(([, value]) => value));
        this.child = this.spawn(executable, argumentsList, {
            ...options,
            detached: process.platform !== 'win32',
            stdio: ['pipe', 'pipe', 'pipe'],
            windowsHide: true,
        });
        this.child.stdout.on('data', this.handleOutput);
        this.child.stderr.on('data', this.handleStderr);
        this.child.stdin.on('error', this.handleError);
        this.child.on('error', this.handleError);
        this.child.on('exit', this.handleExit);
        this.timer = setTimeout(this.handleTimeout, this.timeoutMs);
    }

    async request(method, params) {
        if (this.failure) throw this.failure;
        if (this.closed || !this.child) throw new Error('Agent catalog process is closed');
        if (this.requestSequence >= CATALOG_MAX_REQUESTS) throw new Error('Agent catalog request limit exceeded');
        this.requestSequence += 1;
        const identifier = this.requestSequence;
        const completion = Promise.withResolvers();
        this.pending.set(identifier, completion);
        const message = this.agent === 'codex'
            ? { id: identifier, method, params }
            : { type: 'control_request', request_id: String(identifier), request: { subtype: method, ...params } };
        try {
            this.write(message);
        } catch (error) {
            this.pending.delete(identifier);
            throw error;
        }

        return await completion.promise;
    }

    write(message) {
        if (!this.child || this.closed) throw new Error('Agent catalog process is closed');
        this.child.stdin.write(`${JSON.stringify(message)}\n`);
    }

    countOutput(chunk) {
        this.outputBytes += Buffer.byteLength(chunk);
        if (this.outputBytes > this.maximumOutputBytes) {
            this.fail(new Error('Agent model discovery exceeded its output limit'));
            return false;
        }

        return true;
    }

    handleStderr(chunk) {
        this.countOutput(chunk);
    }

    handleOutput(chunk) {
        if (this.closed || this.failure || !this.countOutput(chunk)) return;
        this.buffer += this.decoder.write(chunk);
        const lines = this.buffer.split(/\r?\n/u);
        this.buffer = lines.pop() ?? '';
        for (const line of lines) {
            if (line.trim().length === 0) continue;
            let message;
            try {
                message = JSON.parse(line);
            } catch {
                this.fail(new Error(`Malformed ${this.agent} model discovery response`));
                return;
            }
            try {
                this.handleMessage(message);
            } catch (error) {
                this.fail(error);
                return;
            }
        }
    }

    handleMessage(message) {
        if (!message || typeof message !== 'object' || Array.isArray(message)) {
            throw new Error('Malformed agent catalog protocol response');
        }
        if (this.agent === 'codex') {
            const completion = this.pending.get(message.id);
            if (!completion) return;
            this.pending.delete(message.id);
            if (message.error) {
                completion.reject(new Error(redactSecrets(message.error.message ?? 'Codex model discovery failed', this.secretValues)));
            }
            else if (Object.hasOwn(message, 'result')) completion.resolve(message.result);
            else completion.reject(new Error('Codex model discovery response is missing its result'));
            return;
        }
        if (message.type !== 'control_response') return;
        const response = message.response;
        if (!response || typeof response.request_id !== 'string') throw new Error('Malformed Claude catalog response');
        const completion = this.pending.get(Number(response.request_id));
        if (!completion) return;
        this.pending.delete(Number(response.request_id));
        if (response.subtype === 'error') {
            completion.reject(new Error(redactSecrets(response.error ?? 'Claude model discovery failed', this.secretValues)));
        }
        else if (response.subtype === 'success' && response.response) completion.resolve(response.response);
        else completion.reject(new Error('Claude model discovery response is missing its result'));
    }

    fail(error) {
        if (this.failure) return;
        this.failure = error;
        for (const completion of this.pending.values()) completion.reject(error);
        this.pending.clear();
    }

    handleError(error) {
        this.fail(new Error(`Could not read ${this.agent} model catalog: ${error.message}`));
    }

    handleExit(code) {
        if (!this.closed) this.fail(new Error(`${this.agent} model discovery exited before completing (code ${code})`));
    }

    handleTimeout() {
        this.fail(new Error(`${this.agent} model discovery timed out`));
    }

    async close() {
        if (this.closed) return;
        this.closed = true;
        clearTimeout(this.timer);
        this.fail(new Error('Agent model discovery was cancelled'));
        await this.terminateProcessTree(this.child);
    }
}

module.exports = { AgentCatalogProcess };

const MAX_CATALOG_PAGES = 20;

function codexModel(model) {
    if (!model || !Array.isArray(model.supportedReasoningEfforts)) throw new Error('Codex returned malformed model capabilities');

    return {
        id: model.model,
        displayName: model.displayName,
        ...(typeof model.description === 'string' ? { description: model.description } : {}),
        hidden: model.hidden,
        reasoningEfforts: model.supportedReasoningEfforts.map(({ reasoningEffort }) => reasoningEffort),
        serviceTiers: model.serviceTiers === undefined ? [] : model.serviceTiers.map(({ id, name, description }) => ({id, name, ...(typeof description === 'string' ? { description } : {})})),
    };
}

/** Read every catalog page and the effective provider using the same process configuration. */
async function readCodexModelCatalog(probe, cwd) {
    await probe.request('initialize', { clientInfo: { name: 'md2', version: '1' }, capabilities: { experimentalApi: true } });
    probe.write({ method: 'initialized', params: {} });
    const models = [];
    const cursors = new Set();
    let cursor;
    let complete = false;
    for (let page = 0; page < MAX_CATALOG_PAGES; page++) {
        const response = await probe.request('model/list', { includeHidden: true, limit: 100, ...(cursor ? { cursor } : {}) });
        if (!response || !Array.isArray(response.data)) throw new Error('Codex returned a malformed model catalog');
        models.push(...response.data.map(codexModel));
        if (response.nextCursor === null) {
            complete = true;
            break;
        }
        if (typeof response.nextCursor !== 'string' || response.nextCursor.length === 0 || cursors.has(response.nextCursor)) {
            throw new Error('Codex returned an invalid or repeated catalog cursor');
        }
        cursor = response.nextCursor;
        cursors.add(cursor);
    }
    if (!complete) throw new Error('Codex model catalog exceeded its page limit');
    const configuration = await probe.request('config/read', { cwd, includeLayers: false });
    if (!configuration?.config || typeof configuration.config !== 'object') throw new Error('Codex provider configuration is missing');
    // Codex's unset model_provider explicitly selects its built-in OpenAI provider.
    const provider = configuration.config.model_provider ?? 'openai';
    const policy = await probe.request('configRequirements/read', {});
    if (!policy || !Object.hasOwn(policy, 'requirements')) throw new Error('Codex capability requirements are missing');
    const fastModeAllowed = policy.requirements?.featureRequirements?.fast_mode !== false;

    return {
        models: fastModeAllowed ? models : models.map((model) => ({...model, serviceTiers: model.serviceTiers.filter(({ id }) => id !== 'priority' && id !== 'fast')})),
        provider,
    };
}

module.exports = { readCodexModelCatalog };

function claudeModel(model) {
    if (!model || typeof model !== 'object') throw new Error('Claude returned a malformed model catalog');
    const reasoningEfforts = model.supportedEffortLevels === undefined
        ? model.supportsEffort === false ? [] : null
        : model.supportedEffortLevels;

    return {
        id: model.value,
        displayName: model.displayName,
        ...(typeof model.description === 'string' ? { description: model.description } : {}),
        ...(model.resolvedModel !== undefined ? { resolvedModel: model.resolvedModel } : {}),
        hidden: false,
        reasoningEfforts,
        serviceTiers: [],
    };
}

/** Initialize Claude without a prompt; the response carries its configured model picker. */
async function readClaudeModelCatalog(probe) {
    const response = await probe.request('initialize', { hooks: null });
    if (!Array.isArray(response.models)) throw new Error('Claude does not expose a model catalog; check its installed version');

    return { models: response.models.map(claudeModel), provider: 'claude' };
}

const CLAUDE_CATALOG_ARGUMENTS = [
    '--print', '--verbose', '--input-format', 'stream-json', '--output-format', 'stream-json',
    '--no-session-persistence', '--strict-mcp-config', '--mcp-config', '{"mcpServers":{}}',
    '--tools', '', '--settings', '{"disableAllHooks":true}',
];

module.exports = { CLAUDE_CATALOG_ARGUMENTS, readClaudeModelCatalog };

import { CODEX_MAX_THINKING_LEVEL, THINKING_LEVELS, validateSpeedMode } from './agent_profiles.mjs';

function requiredText(value, field, source) {
    if (typeof value !== 'string' || value.length === 0 || value.trim() !== value) {
        throw new Error(`Invalid ${field} in ${source}`);
    }

    return value;
}

/** Validate the host catalog at the bridge boundary without inferring provider capabilities. */
export function validateAgentModelCatalog(value, source = 'agent model catalog') {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Invalid catalog in ${source}`);
    requiredText(value.agent, 'agent', source);
    requiredText(value.provider, 'provider', source);
    requiredText(value.source, 'source', source);
    if (!['runtime', 'configured'].includes(value.source)) throw new Error(`Invalid catalog source in ${source}`);
    if (!Number.isFinite(value.fetchedAt)) throw new Error(`Invalid catalog timestamp in ${source}`);
    if (!Array.isArray(value.models) || value.models.length === 0) throw new Error(`Model catalog is empty in ${source}`);
    const identifiers = new Set();
    for (const model of value.models) {
        if (!model || typeof model !== 'object' || Array.isArray(model)) throw new Error(`Invalid model in ${source}`);
        const identifier = requiredText(model.id, 'model ID', source);
        requiredText(model.displayName, 'model display name', source);
        if (identifiers.has(identifier)) throw new Error(`Duplicate model ID ${identifier} in ${source}`);
        identifiers.add(identifier);
        if (typeof model.hidden !== 'boolean') throw new Error(`Invalid model visibility in ${source}`);
        if (model.resolvedModel !== undefined) requiredText(model.resolvedModel, 'resolved model', source);
        if (model.reasoningEfforts !== null && (!Array.isArray(model.reasoningEfforts)
            || model.reasoningEfforts.some((effort) => typeof effort !== 'string' || effort.length === 0))) {
            throw new Error(`Invalid model reasoning efforts in ${source}`);
        }
        if (!Array.isArray(model.serviceTiers)) throw new Error(`Invalid model service tiers in ${source}`);
        const tiers = new Set();
        for (const tier of model.serviceTiers) {
            requiredText(tier.id, 'service tier ID', source);
            requiredText(tier.name, 'service tier name', source);
            if (tiers.has(tier.id)) throw new Error(`Duplicate service tier ${tier.id} in ${source}`);
            tiers.add(tier.id);
        }
    }

    return value;
}

/** Resolve a wire ID or an advertised Claude alias without modifying the stored selection. */
export function findCatalogModel(catalog, model) {
    return catalog.models.find(({ id }) => id === model)
        ?? catalog.models.find(({ resolvedModel }) => resolvedModel === model)
        ?? null;
}

export function modelThinkingLevels(agent, model) {
    if (!model) return ['none'];
    if (model.reasoningEfforts === null) return [...THINKING_LEVELS];

    return THINKING_LEVELS.filter((level) => level === 'none'
        || model.reasoningEfforts.includes(agent === 'codex' && level === 'max' ? CODEX_MAX_THINKING_LEVEL : level));
}

/** OpenAI advertises the Fast transport tier as priority; never infer support from a model name. */
export function modelFastTier(catalog, model) {
    if (catalog.agent !== 'codex' || catalog.provider !== 'openai' || !model) return null;

    return model.serviceTiers.find(({ id }) => id === 'priority' || id === 'fast') ?? null;
}

/** Validate requested settings before launching a provider or starting another inference turn. */
export function validateCatalogSelection(catalog, selection, source = 'agent execution') {
    const model = findCatalogModel(catalog, selection.model);
    if (!model) {
        throw new Error(`Model ${selection.model} is not advertised by ${catalog.agent} in ${source}. Refresh models or check the configured client.`);
    }
    if (selection.thinkingLevel !== undefined && !modelThinkingLevels(catalog.agent, model).includes(selection.thinkingLevel)) {
        throw new Error(`Model ${selection.model} does not support reasoning level ${selection.thinkingLevel}`);
    }
    const speedMode = selection.speedMode === undefined ? 'default' : validateSpeedMode(selection.speedMode, source);
    if (speedMode !== 'default' && (catalog.agent !== 'codex' || catalog.provider !== 'openai')) {
        throw new Error('Explicit speed settings are supported only by the OpenAI Codex provider');
    }
    const fastTier = modelFastTier(catalog, model);
    if (speedMode === 'fast' && !fastTier) throw new Error(`Fast mode is not advertised for ${selection.model}`);

    return { model, serviceTier: speedMode === 'fast' ? fastTier.id : speedMode === 'standard' ? 'default' : undefined };
}

import { calculateMainToolbarLayout, TOOLBAR_SEARCH_WIDTH, type MainToolbarLayout } from './main_toolbar_layout';

interface ToolbarElements {
    navigation: HTMLElement;
    project: HTMLElement;
    safeArea: HTMLElement;
    search: HTMLElement;
    toolbar: HTMLElement;
    utilities: HTMLElement;
}

// scrollWidth rounds CSS pixels; leave room for fractional native font metrics.
const TEXT_MEASUREMENT_ALLOWANCE = 2;
const INITIAL_LAYOUT: MainToolbarLayout = { searchPresentation: 'full', searchWidth: TOOLBAR_SEARCH_WIDTH, titleLeft: 0, titleWidth: 0 };

/** Owns header measurements and observes native safe-area, navigation, font, and project-name changes. */
export class MainToolbarLayoutService extends EventTarget {
    private elements: ToolbarElements | null = null;
    private mutationObserver: MutationObserver | null = null;
    private resizeObserver: ResizeObserver | null = null;
    private snapshot: MainToolbarLayout = INITIAL_LAYOUT;

    getSnapshot = () => this.snapshot;

    connect(elements: ToolbarElements) {
        this.disconnect();
        this.elements = elements;
        this.resizeObserver = new ResizeObserver(this.updateLayout);
        for (const element of Object.values(elements)) this.resizeObserver.observe(element);
        const metrics = elements.search.querySelector('[data-search-metrics]');
        if (!metrics) throw new Error('Header search measurements are missing');
        this.resizeObserver.observe(metrics);
        this.mutationObserver = new MutationObserver(this.updateLayout);
        this.mutationObserver.observe(elements.project, { characterData: true, childList: true, subtree: true });
        this.updateLayout();
    }

    disconnect() {
        this.resizeObserver?.disconnect();
        this.mutationObserver?.disconnect();
        this.resizeObserver = null;
        this.mutationObserver = null;
        this.elements = null;
    }

    private updateLayout = () => {
        if (!this.elements) return;
        const { navigation, project, safeArea, search, toolbar, utilities } = this.elements;
        const safeAreaRectangle = safeArea.getBoundingClientRect();
        if (safeAreaRectangle.width === 0) return;
        const metrics = search.querySelector<HTMLElement>('[data-search-metrics]');
        const label = search.querySelector<HTMLElement>('[data-search-label]');
        const word = search.querySelector<HTMLElement>('[data-search-word]');
        if (!metrics || !label || !word) throw new Error('Header search measurements are missing');
        const labelWidth = label.getBoundingClientRect().width;
        const fullWidth = Math.ceil(metrics.getBoundingClientRect().width);
        const gap = Number.parseFloat(getComputedStyle(metrics).columnGap);
        const labelElement = project.querySelector<HTMLElement>('[data-testid="project-name-label"]');
        const measurements = {
            navigationWidth: Math.ceil(navigation.getBoundingClientRect().width),
            safeAreaLeft: safeAreaRectangle.left - toolbar.getBoundingClientRect().left,
            safeAreaWidth: safeAreaRectangle.width,
            searchWidths: {
                full: fullWidth,
                search: Math.ceil(fullWidth - labelWidth + word.getBoundingClientRect().width),
                shortcut: Math.ceil(fullWidth - labelWidth - gap),
            },
            titleWidth: labelElement ? labelElement.scrollWidth + TEXT_MEASUREMENT_ALLOWANCE : 0,
            utilitiesWidth: Math.ceil(utilities.getBoundingClientRect().width),
            viewportWidth: toolbar.getBoundingClientRect().width,
        };
        const nextLayout = calculateMainToolbarLayout(measurements);
        if (nextLayout.searchPresentation === this.snapshot.searchPresentation && nextLayout.searchWidth === this.snapshot.searchWidth
            && nextLayout.titleLeft === this.snapshot.titleLeft && nextLayout.titleWidth === this.snapshot.titleWidth) return;
        this.snapshot = nextLayout;
        this.dispatchEvent(new Event('layoutChanged'));
    };
}

export const mainToolbarLayoutService = new MainToolbarLayoutService();

/** React's external-store adapter uses the service's standard EventTarget lifecycle. */
export function subscribeToolbarLayout(onStoreChange: () => void) {
    mainToolbarLayoutService.addEventListener('layoutChanged', onStoreChange);

    return () => mainToolbarLayoutService.removeEventListener('layoutChanged', onStoreChange);
}

import { Box, Tab as MuiTab, Tabs, Toolbar } from '@mui/material';
import { useLayoutEffect, useRef, useSyncExternalStore, type SyntheticEvent } from 'react';
