import { useCallback, useEffect, useSyncExternalStore } from 'react';
import type { AgentProfile } from '../../data/agent_profiles';
import type { ProjectReference } from '../../data/data_types';
import {
    agentCapabilitiesService,
    agentCatalogKey,
    type AgentCapabilitiesService,
} from '../../services/agents/agent_capabilities_service';

/** Subscribe to one host/profile/worktree catalog; discovery never runs during rendering. */
export function useAgentModelCatalog(
    profile: AgentProfile | null,
    project: ProjectReference | null,
    service: AgentCapabilitiesService = agentCapabilitiesService,
) {
    const key = profile ? agentCatalogKey(profile, project) : '';
    const connection = service.getConnectionIdentity();
    const snapshot = useSyncExternalStore(
        (onStoreChange) => {
            service.addEventListener(`catalog:${key}`, onStoreChange);

            return () => service.removeEventListener(`catalog:${key}`, onStoreChange);
        },
        () => service.getCatalogSnapshot(key),
        () => service.getCatalogSnapshot(key),
    );
    useEffect(() => {
        if (profile && !snapshot.loading && !snapshot.error && (!snapshot.catalog || snapshot.stale)) {
            void service.loadCatalog(profile, project, snapshot.stale);
        }
    }, [connection, key, profile, project, service, snapshot]);
    const refresh = useCallback(async () => {
        if (profile) await service.loadCatalog(profile, project, true);
    }, [profile, project, service]);

    return { ...snapshot, refresh };
}

import type { ActionRunSettingsStore } from '../../services/actions/action_run_settings_service';
import { worktreeService } from '../../services/project/worktree_service';
import { useCardWorktreeByInternalId } from '../card_view/use_project_card';
import { useProjectReference } from './use_project_reference';
import { useProjectActionWorktree, useProjectActionWorktreeBranch, useWorktrees } from './use_worktrees';
import { useMergeConflict } from './use_merge_conflict';

/** Discover capabilities in the same assigned checkout as a card or project action. */
export function useActionCatalogProject(store: ActionRunSettingsStore) {
    const project = useProjectReference();
    const cardWorktree = useCardWorktreeByInternalId(store.cardInternalId);
    const projectWorktree = useProjectActionWorktree();
    const projectWorktreeBranch = useProjectActionWorktreeBranch();
    const records = useWorktrees();
    const { session } = useMergeConflict();
    if (project && store.contextKind === 'merge-conflict') {
        if (!session) return { error: 'Merge conflict model discovery requires an active session', project: null };
        const branch = session.repositoryRoot === project.rootPath
            ? project.branch
            : records.find((record) => record.path === session.repositoryRoot)?.branch;
        if (!branch) return { error: 'Merge conflict checkout is unavailable', project: null };

        return { error: null, project: { ...project, branch, id: session.repositoryRoot, rootPath: session.repositoryRoot } };
    }
    if (!project || (store.contextKind !== 'card' && store.contextKind !== 'project')) return { error: null, project };
    const assignment = store.contextKind === 'card'
        ? { branch: cardWorktree?.branch, worktree: cardWorktree?.worktree, worktreeError: cardWorktree?.error }
        : { branch: projectWorktreeBranch, worktree: projectWorktree };
    const { error, record } = worktreeService.getAssignmentState(assignment);
    if (error) return { error, project: null };
    if (!record) return { error: null, project };
    if (!record.branch) return { error: 'Selected worktree has no branch', project: null };

    return { error: null, project: { ...project, branch: record.branch, id: record.path, rootPath: record.path } };
}

import type { SearchPresentation } from '../search/search_field_styles';

export const TOOLBAR_SEARCH_WIDTH = 260;
export const TOOLBAR_ICON_WIDTH = 32;
export const TOOLBAR_PADDING = 12;
export const TOOLBAR_GROUP_GAP = 8;
export const TOOLBAR_TITLE_CLEARANCE = 16;
const MINIMUM_TITLE_WIDTH = 96;

export interface MainToolbarMeasurements {
    navigationWidth: number;
    safeAreaLeft: number;
    safeAreaWidth: number;
    searchWidths: { full: number; search: number; shortcut: number };
    titleWidth: number;
    utilitiesWidth: number;
    viewportWidth: number;
}

export interface MainToolbarLayout {
    searchPresentation: SearchPresentation;
    searchWidth: number;
    titleLeft: number;
    titleWidth: number;
}

/** Allocate measured content inside the native safe area, preserving the shortcut before title space. */
export function calculateMainToolbarLayout(measurements: MainToolbarMeasurements): MainToolbarLayout {
    const { navigationWidth, safeAreaLeft, safeAreaWidth, searchWidths, titleWidth, utilitiesWidth, viewportWidth } = measurements;
    const titleStart = TOOLBAR_PADDING + navigationWidth + TOOLBAR_TITLE_CLEARANCE;
    const rightBase = TOOLBAR_PADDING + utilitiesWidth + TOOLBAR_GROUP_GAP + TOOLBAR_TITLE_CLEARANCE;
    const availableWidth = Math.max(0, safeAreaWidth - titleStart - rightBase);
    const searchBudget = Math.max(0, availableWidth - MINIMUM_TITLE_WIDTH);
    const presentations = ['full', 'search', 'shortcut'] as const;
    const fittingPresentation = presentations.find((presentation) => searchWidths[presentation] <= searchBudget);
    const searchPresentation = fittingPresentation ?? (searchWidths.shortcut <= availableWidth ? 'shortcut' : 'icon');
    const searchWidth = fittingPresentation
        ? Math.min(TOOLBAR_SEARCH_WIDTH, searchBudget)
        : searchPresentation === 'shortcut' ? searchWidths.shortcut : TOOLBAR_ICON_WIDTH;
    const visibleTitleWidth = Math.min(titleWidth, Math.max(0, availableWidth - searchWidth));
    const maximumTitleLeft = Math.max(titleStart, safeAreaWidth - rightBase - searchWidth - visibleTitleWidth);
    const centeredTitleLeft = (viewportWidth - visibleTitleWidth) / 2 - safeAreaLeft;
    const titleLeft = Math.min(maximumTitleLeft, Math.max(titleStart, centeredTitleLeft));

    return { searchPresentation, searchWidth, titleLeft, titleWidth: visibleTitleWidth };
}

