const OUTPUT_COMMAND_ADAPTERS = new Map([
    ['claude', buildClaudeOutputCommand],
    ['codex', buildCodexOutputCommand],
])

const STREAMING_COMMAND_ADAPTERS = new Map([
    ['claude', buildClaudeStreamingCommand],
