            ...(costUsd !== undefined || baseline.costUsd !== undefined ? { costUsd: costUsd ?? baseline.costUsd } : {}),
            ...(typeof event.uuid === 'string' ? { resultId: event.uuid } : {}),
            ...(cumulativeTokens ? { tokens: cumulativeTokens } : {}),
